	//   }
	//
	// inverse swap
	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "data": {
	//             "order": {
	//                 "symbol": "SOL-USD",
	//                 "orderId": "1816002957423951872",
	//                 "side": "BUY",
	//                 "positionSide": "Long",
	//                 "type": "Pending",
	//                 "quantity": 0,
	//                 "origQty": "0",
