	//                 },
	//                 "stopLoss": {
	//                     "type": "",
	//                     "quantity": 0,
	//                     "stopPrice": 0,
	//                     "price": 0,
	//                     "workingType": "",
	//                     "stopGuaranteed": ""
	//                 },
	//                 "advanceAttr": 0,
	//                 "positionID": 0,
	//                 "takeProfitEntrustPrice": 0,
	//                 "stopLossEntrustPrice": 0,
	//                 "orderType": "",
	//                 "workingType": ""
	//             }
	//         }
	//     }
	//
	// linear swap
	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "data": {
	//          "order": {
	//            "symbol": "LINK-USDT",
	//            "orderId": 1597783850786750464,
	//            "side": "BUY",
	//            "positionSide": "LONG",
	//            "type": "TRIGGER_MARKET",
