/**
 * @method
 * @name bingx#setMargin
 * @description Either adds or reduces margin in an isolated position in order to set the margin to a specific value
 * @see https://bingx-api.github.io/docs-v3/#/en/Swap/Trades%20Endpoints/Modify%20Isolated%20Position%20Margin
 * @param {string} symbol unified market symbol of the market to set margin in
 * @param {float} amount the amount to set the margin to
 * @param {object} [params] parameters specific to the exchange API endpoint
 * @returns {object} A [margin structure]{@link https://docs.ccxt.com/?id=margin-structure}
 */
func (this *Bingx) SetMarginAsync(symbol any, amount any, optionalArgs ...any) <-chan AsyncResult[MarginModification] {
	ch := make(chan AsyncResult[MarginModification], 1)
	go this.setMarginBody(ch, symbol, amount, optionalArgs...)
	return ch
}
func (this *Bingx) setMarginBody(ch chan AsyncResult[MarginModification], symbol any, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var typeVar *int64 = this.SafeInteger(params, "type") // 1 increase margin 2 decrease margin
	if typeVar == nil {
		panic(ArgumentsRequired(this.Id + " setMargin() requires a type parameter either 1 (increase margin) or 2 (decrease margin)"))
	}
	if !this.InArray(typeVar, []any{1, 2}) {
		panic(ArgumentsRequired(this.Id + " setMargin() requires a type parameter either 1 (increase margin) or 2 (decrease margin)"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
		"amount": this.AmountToPrecision(market["symbol"], amount),
		"type":   typeVar,
	}

	r1 := <-this.SwapV2PrivatePostTradePositionMargin(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "amount": 1,
	//        "type": 1
	//    }
	//
	ch <- AsyncResult[MarginModification]{Value: MarginModificationFromMap(this.ParseMarginModification(response, market))}
	return nil
}
func (this *Bingx) ParseMarginModification(data any, optionalArgs ...any) map[string]any {
	//
	//    {
	//        "code": 0,
	//        "msg": "",
	//        "amount": 1,
	//        "type": 1
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var typeVar *string = this.SafeString(data, "type")
	return map[string]any{
		"info":   data,
		"symbol": this.SafeString(market, "symbol"),
		"type": func() string {
			if typeVar != nil && *typeVar == "1" {
				return "add"
			}
			return "reduce"
		}(),
		"marginMode": "isolated",
		"amount":     this.SafeNumber(data, "amount"),
		"total":      this.SafeNumber(data, "margin"),
		"code":       this.SafeString(market, "settle"),
		"status":     nil,
		"timestamp":  nil,
		"datetime":   nil,
	}
}

