	//
	//     {
	//         "code": 0,
	//         "msg": "",
	//         "timestamp": 1767789967284,
	//         "data": [
	//             {
	//                 "tier": "Tier 1",
	//                 "symbol": "ETH-USDT",
	//                 "minPositionVal": "0",
	//                 "maxPositionVal": "900000",
	//                 "maintMarginRatio": "0.003300",
	//                 "maintAmount": "0.000000"
	//             }
	//         ]
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

